173	export async function updateWorkspace(id: string, patch: Partial<Workspace>): Promise<Workspace | null> {
174	  const ws = workspaces.get(id)
175	  if (!ws) return null
176	  // 렌더러가 보낸 값을 **타입까지 확인**하고 받는다. 2026-09-07 임무 19 실측:
177	  // 검증이 없어 `color` 에 객체 `{}` 가 그대로 저장·영속됐다(UI 가 그 값을 CSS 로 쓴다).
178	  // `name` 은 문자열이 아니면 `.trim()` 에서 예외가 나 업데이트 자체가 실패했다.
179	  const str = (v: unknown, fallback: string): string =>
180	    (typeof v === 'string' && v.trim() ? v.trim() : fallback)
181	  const next: Workspace = {
182	    ...ws,
183	    name: patch.name !== undefined ? str(patch.name, ws.name) : ws.name,
184	    color: patch.color !== undefined ? (str(patch.color, ws.color) as Workspace['color']) : ws.color,
