195	export async function removeWorkspace(id: string): Promise<{ removed: boolean; newActiveId: string }> {
196	  if (workspaces.size <= 1) return { removed: false, newActiveId: activeId }
197	  const ws = workspaces.get(id)
198	  if (!ws) return { removed: false, newActiveId: activeId }
199	  const wasActive = activeId === id
200	  workspaces.delete(id)
201	  // 인덱스 재정렬
202	  getOrderedList().forEach((w, i) => { w.position = i })
203	  if (wasActive) {
204	    const first = getOrderedList()[0]
205	    activeId = first ? first.id : ''
206	  }
207	  await persist()
208	  workspaceEvents.emit('removed', { id, partition: ws.partition })
209	  // 활성 워크스페이스를 지웠으면 새 활성으로 'activated' 를 발생시켜야 tab-service 가 새 워크스페이스의
210	  // 탭을 보이게 하고(레이아웃 재적용) 탭이 없으면 홈 탭을 만든다 — 안 그러면 빈 창이 된다.
211	  if (wasActive && activeId) workspaceEvents.emit('activated', { id: activeId, prev: id })
212	  workspaceEvents.emit('changed')
213	  return { removed: true, newActiveId: activeId }
214	}
215	
216	export async function setActiveWorkspace(id: string): Promise<boolean> {
217	  if (!workspaces.has(id)) return false
218	  if (activeId === id) return true
219	  const prev = activeId
220	  activeId = id
221	  await persist()
222	  workspaceEvents.emit('activated', { id, prev })
223	  workspaceEvents.emit('changed')
224	  return true
225	}
226	
227	export async function reorderWorkspaces(orderedIds: string[]): Promise<void> {
228	  orderedIds.forEach((id, i) => {
229	    const w = workspaces.get(id)
230	    if (w) w.position = i
231	  })
232	  await persist()
233	  workspaceEvents.emit('changed')
234	}
235	
236	export function nextWorkspaceId(direction: 1 | -1): string | null {
237	  const list = getOrderedList()
238	  if (list.length <= 1) return null
239	  const i = list.findIndex((w) => w.id === activeId)
240	  if (i < 0) return list[0]?.id ?? null
241	  const next = (i + direction + list.length) % list.length
242	  return list[next]?.id ?? null
243	}
